#include <utility>

inline void* const kInvalid{ reinterpret_cast<void*>(-1) };
using CloseFn = void (*)(void*);

class ScopedResource
{
public:
    ScopedResource(void* value, CloseFn close) : m_value{ value }, m_close{ close } {}
    ~ScopedResource() { reset(); }

    ScopedResource(const ScopedResource&) = delete;
    ScopedResource& operator=(const ScopedResource&) = delete;

    ScopedResource(ScopedResource&& other) noexcept
        : m_value{ std::exchange(other.m_value, nullptr) }, m_close{ other.m_close } {}

    ScopedResource& operator=(ScopedResource&& other) noexcept
    {
        if (this != &other)
        {
            reset();
            m_value = std::exchange(other.m_value, nullptr);
            m_close = other.m_close;
        }
        return *this;
    }

    void* get() const { return m_value; }
    bool owns() const { return m_value != nullptr && m_value != kInvalid; }

    void* release() { return std::exchange(m_value, nullptr); }

    void reset()
    {
        if (owns() && m_close) m_close(m_value);
        m_value = nullptr;
    }

private:
    void* m_value;
    CloseFn m_close;
};

unitTests:
#include <cstdint>
#include <type_traits>
static int g_closed{ 0 };
static void* g_lastClosed{ nullptr };
static void fakeClose(void* v) { ++g_closed; g_lastClosed = v; }
static void* fake(int n) { return reinterpret_cast<void*>(static_cast<std::intptr_t>(n)); }
TEST("closes once when it goes out of scope") { g_closed = 0; { ScopedResource r{ fake(0x40), &fakeClose }; CHECK(r.owns()); } CHECK_EQ(g_closed, 1); CHECK(g_lastClosed == fake(0x40)); }
TEST("empty values are never closed") { g_closed = 0; { ScopedResource a{ nullptr, &fakeClose }; ScopedResource b{ kInvalid, &fakeClose }; CHECK(!a.owns()); CHECK(!b.owns()); } CHECK_EQ(g_closed, 0); }
TEST("release gives up ownership") { g_closed = 0; void* v{ nullptr }; { ScopedResource r{ fake(0x44), &fakeClose }; v = r.release(); CHECK(!r.owns()); } CHECK_EQ(g_closed, 0); CHECK(v == fake(0x44)); }
TEST("reset closes now") { g_closed = 0; ScopedResource r{ fake(0x48), &fakeClose }; r.reset(); CHECK_EQ(g_closed, 1); CHECK(!r.owns()); r.reset(); CHECK_EQ(g_closed, 1); }
TEST("moving passes ownership") { g_closed = 0; { ScopedResource a{ fake(0x4C), &fakeClose }; ScopedResource b{ std::move(a) }; CHECK(!a.owns()); CHECK(b.owns()); } CHECK_EQ(g_closed, 1); }
TEST("move assignment closes the old value first")
{
    g_closed = 0;
    {
        ScopedResource a{ fake(0x50), &fakeClose };
        ScopedResource b{ fake(0x54), &fakeClose };
        b = std::move(a);
        CHECK_EQ(g_closed, 1);
        CHECK(g_lastClosed == fake(0x54));
        CHECK(b.get() == fake(0x50));
    }
    CHECK_EQ(g_closed, 2);
}
TEST("cannot be copied") { CHECK(!std::is_copy_constructible_v<ScopedResource>); CHECK(!std::is_copy_assignable_v<ScopedResource>); }

